import { useEffect, useMemo, useRef, useState } from 'react';
import { Navigate, useLocation, useNavigate, useSearchParams } from 'react-router-dom';
import { directionOf, type LanguageCode } from '@lexpad/core';
import { Icon } from '@/components/ui/Icon.js';
import { Skeleton } from '@/components/ui/Spinner.js';
import {
  addNotebook,
  addWord,
  importWords,
  patchSettings,
  updateNotebook,
  type ImportRow,
  type WordDraft,
} from '@/db/mutations.js';
import { setMeta } from '@/db/schema.js';
import { generateCardWithJob } from '@/features/ai/generate.js';
import { ReportButton } from '@/features/report/ReportButton.js';
import { cardSnapshot } from '@/features/report/report.js';
import { isApiError } from '@/api/errors.js';
import { pushAll } from '@/sync/worker.js';
import { listNotebooks } from '@/db/repo.js';
import { getActiveNotebook } from '@/db/repo.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { t } from '@/i18n/index.js';
import { localTimeZone } from '@/lib/format.js';
import { cx } from '@/lib/cx.js';
import { useTheme } from '@/lib/theme.js';
import { syncSoon } from '@/sync/store.js';
import { LANGUAGE_NAMES, MEANING_LANGUAGES, TARGET_LANGUAGES } from '@/features/settings/data.js';
import {
  canSwap,
  looksReversed,
  parseFile,
  type LanguageHints,
  type ParsedFile,
  swapColumns,
  withoutDuplicates,
} from '@/features/settings/transfer/parse.js';
import { PreviewList } from '@/features/settings/transfer/ImportPreview.js';
import { PasteListSheet } from '@/features/settings/transfer/PasteListSheet.js';
import { parseLocal, readImport } from '@/features/settings/transfer/read.js';
import {
  IMPORT_ACCEPT,
  importErrorMessage,
  sendImport,
  serverImportFailure,
  uploadFailure,
  waitForImport,
} from '@/features/settings/importJob.js';
import {
  kindOf,
  pastedFile,
  reportImport,
  reportImportFailure,
  type ImportedFile,
  type ImportKind,
} from '@/features/settings/importOutcome.js';
import { useSync } from '@/sync/store.js';
import { settingsPath } from '@/features/settings/paths.js';
import { likelyLanguage } from '@/lib/deviceLanguage.js';
import { overImportLimit } from '@/lib/useConfig.js';
import { Upgrade } from '@/features/billing/Upgrade.js';
import { changeNeedsPro, useBilling } from '@/features/billing/state.js';
import { LanguagePicker } from './LanguagePicker.js';
import styles from './Onboarding.module.css';

/**
 * Three questions, then the first card (2026-10-09). The look of the app is
 * the device's own until it is changed in Settings → Appearance; the five
 * boxes were shown once already, on the introduction, and the new learner's
 * journey teaches the rest when it happens; the daily reminder is offered on
 * the first session's summary, once there is something to be reminded of.
 */
const STEPS = ['target', 'meaning', 'first'] as const;
type Step = (typeof STEPS)[number];

/**
 * What each step's history entry carries. Every step is its own entry, so
 * the browser's Back and Android's back key go back a question rather than
 * out of the flow, and a reload lands on the same question with the
 * languages already chosen. `run` names one pass through the flow, so an
 * entry of a pass that has finished is never shown again.
 */
interface StepState {
  run?: string;
  /** Read back from history, so checked rather than trusted. */
  step?: unknown;
  target?: string;
  meaning?: string;
}

/** The passes through onboarding that ended in this page's lifetime. */
const finishedRuns = new Set<string>();

interface Answers {
  targetLang: LanguageCode;
  /**
   * Undefined until the question is answered. For somebody's own language a
   * wrong default is worse than none: they would notice, and a preselected
   * wrong answer is easy to walk past.
   */
  meaningLang: LanguageCode | undefined;
  headword: string;
  /** The card the model wrote for the headword, when the user asked for it. */
  card?: WordDraft;
  meaning: string;
  imported: ImportRow[];
  /** Whether the imported rows were turned round, by the reader or by the learner. */
  importSwapped: boolean;
  /**
   * An Anki package or a Kindle's vocab.db, which the server reads into the
   * notebook once it exists; it is sent at the end with everything else.
   */
  serverFile?: { file: File; source: 'anki' | 'kindle' };
}

function isLanguage(value: unknown, list: readonly LanguageCode[]): value is LanguageCode {
  return typeof value === 'string' && (list as readonly string[]).includes(value);
}

/**
 * What the flow starts with: the languages a reloaded step had already
 * chosen. A learner who came through the introduction never sees these
 * questions (onboarding v2 asks them before the account; see FirstCard):
 * they are for an account made on the sign-in page, or a new device whose
 * notebook is empty.
 *
 * The second question — what do you already speak? — starts on whatever
 * the device says its owner speaks, and on nothing at all when the device
 * says nothing we recognise. It used to start on Persian, which was true of
 * the first few users and of nobody since.
 */
function startingAnswers(kept: StepState): Answers {
  return {
    targetLang: isLanguage(kept.target, TARGET_LANGUAGES) ? kept.target : 'en',
    meaningLang: isLanguage(kept.meaning, MEANING_LANGUAGES) ? kept.meaning : likelyLanguage(),
    headword: '',
    meaning: '',
    imported: [],
    importSwapped: false,
  };
}

/**
 * First run: two questions and the learner's own first word, then a
 * notebook with something in it and one card to answer. Nothing is written
 * until the last step, so going back costs nothing. Picking a language
 * advances on its own, as the prototype does — the Continue button is there
 * for the steps that need it.
 */
export function Onboarding(): React.JSX.Element {
  const navigate = useNavigate();
  const location = useLocation();
  const [params] = useSearchParams();
  // Settings reuses the two language questions to change an existing
  // notebook's languages, then returns; nothing else of the flow runs.
  const editing = params.get('edit') === '1';
  const kept = useMemo(() => (location.state as StepState | null) ?? {}, [location.state]);
  const current = useLiveQuery(getActiveNotebook, undefined, []);
  const [run] = useState(() => kept.run ?? `${String(Date.now())}-${String(Math.random()).slice(2, 8)}`);
  // The initial answers are read once, so a device that changes language
  // mid-flow does not move the ground under somebody.
  const [start] = useState(() => startingAnswers(kept));
  const [picked, setPicked] = useState<Answers | undefined>(undefined);
  // While changing an existing notebook's languages, the current pair shows
  // until the user picks otherwise — derived, so nothing has to be copied in.
  const answers: Answers =
    picked ??
    (editing && current
      ? { ...start, targetLang: current.targetLang, meaningLang: current.meaningLang }
      : start);
  const [error, setError] = useState<string | undefined>(undefined);
  const [busy, setBusy] = useState(false);
  const [importingAnki, setImportingAnki] = useState(false);
  // `?import=paste` comes from the site's Anki and Quizlet pages: the paste
  // box opens once the languages are chosen, which is where a list can go.
  const [pasting, setPasting] = useState(false);
  const askedToPaste = params.get('import') === 'paste';
  const syncNow = useSync((state) => state.syncNow);
  const finishing = useRef(false);
  // The pass is marked over once this screen has gone, not before: marked
  // while it is still on screen, the next render would send it to Today
  // instead of the first card.
  const finished = useRef(false);
  useEffect(
    () => () => {
      if (finished.current) finishedRuns.add(run);
    },
    [run],
  );
  const fileInput = useRef<HTMLInputElement>(null);
  /** What kind of import the picked list came from, for its anonymous outcome. */
  const importKind = useRef<ImportKind>('other');
  /** The file (or pasted list) the picked words came from, for the server's one-day copy. */
  const importFile = useRef<ImportedFile | undefined>(undefined);
  /** Rows of that file left out (unreadable or repeated), so a partial import can keep its file. */
  const importSkipped = useRef(0);
  const { theme, palette } = useTheme();
  // Changing an existing notebook's languages can be part of Pro (see
  // changeNeedsPro), so the edit asks the plan and counts the notebooks the
  // learner owns besides this one. A first run needs neither.
  const billing = useBilling((s) => s.state);
  const ensureBilling = useBilling((s) => s.ensure);
  useEffect(() => {
    if (editing) ensureBilling();
  }, [editing, ensureBilling]);
  const notebooks = useLiveQuery(() => listNotebooks(), undefined, []);
  // The free language a refused change would leave, said before anything is
  // written: a change written locally against a refusal would be parked by
  // sync and the notebook would show a pair the server never took.
  const [leaving, setLeaving] = useState<string | undefined>(undefined);
  const [paywall, setPaywall] = useState(false);

  // A step with nothing before it chosen (a reload that lost the answers)
  // starts again from the question that is missing.
  const wanted =
    typeof kept.step === 'number' ? Math.min(Math.max(Math.trunc(kept.step), 0), STEPS.length - 1) : 0;
  const index = wanted >= 2 && answers.meaningLang === undefined ? 1 : wanted;
  const step: Step = STEPS[index] ?? 'target';
  const set = (change: Partial<Answers>): void => {
    setPicked({ ...answers, ...change });
  };

  const next = (change: Partial<Answers> = {}): void => {
    setError(undefined);
    const after = { ...answers, ...change };
    void navigate(`${location.pathname}${location.search}`, {
      state: {
        run,
        step: Math.min(STEPS.length - 1, index + 1),
        target: after.targetLang,
        ...(after.meaningLang === undefined ? {} : { meaning: after.meaningLang }),
      } satisfies StepState,
    });
  };

  /** The languages chosen so far, which place a sheet's named columns. */
  const hints = (): LanguageHints => ({ targetLang: answers.targetLang, meaningLang: answers.meaningLang });

  /** A file or a pasted list, once read: turned round if need be, shown. */
  const takeParsed = (parsed: ParsedFile): void => {
    const targetLang = parsed.targetLang ?? answers.targetLang;
    const meaningLang = parsed.meaningLang ?? answers.meaningLang;
    const reversed = meaningLang !== undefined && looksReversed(parsed.rows, targetLang, meaningLang);
    const rows = withoutDuplicates(reversed ? swapColumns(parsed.rows) : parsed.rows, []);
    importSkipped.current = parsed.skipped + (parsed.rows.length - rows.length);
    const { serverFile: _dropped, ...rest } = answers;
    setPicked({
      ...rest,
      imported: rows,
      importSwapped: reversed,
      ...(parsed.targetLang === undefined ? {} : { targetLang: parsed.targetLang }),
      ...(parsed.meaningLang === undefined ? {} : { meaningLang: parsed.meaningLang }),
    });
  };

  const offeredPaste = useRef(false);
  useEffect(() => {
    if (!askedToPaste || step !== 'first' || offeredPaste.current) return;
    offeredPaste.current = true;
    setPasting(true);
  }, [askedToPaste, step]);

  const readPasted = (text: string): void => {
    setPasting(false);
    setError(undefined);
    importKind.current = 'paste';
    importFile.current = pastedFile(text);
    try {
      takeParsed(parseFile('pasted.txt', text, hints()));
    } catch (cause) {
      reportImportFailure('paste', cause, importFile.current);
      setError(importErrorMessage(cause));
    }
  };

  const readFile = async (file: File): Promise<void> => {
    setError(undefined);
    importKind.current = 'other';
    importFile.current = { data: file, name: file.name };
    try {
      const read = await readImport(file);
      importKind.current = kindOf(read);
      if (read.kind === 'server') {
        if (overImportLimit(read.file.size)) {
          reportImport({ kind: read.source, outcome: 'failed', errorCode: 'too_large' });
          setError(t('settings.importTooLarge'));
          return;
        }
        set({ serverFile: { file: read.file, source: read.source }, imported: [], importSwapped: false });
        return;
      }
      takeParsed(parseLocal(file.name, read, hints()));
    } catch (cause) {
      reportImportFailure(importKind.current, cause, importFile.current);
      setError(importErrorMessage(cause));
    }
  };

  /** Writes everything at once, then hands the user their first card. */
  const finish = async (): Promise<void> => {
    // A second tap while the first is still writing must not run again;
    // state alone is too slow to stop it.
    if (finishing.current) return;
    finishing.current = true;
    setBusy(true);
    setError(undefined);
    try {
      const timeZone = localTimeZone();
      // An account that already owns a notebook is not being set up; it got
      // here by mistake, or the pull landed while the questions were open.
      // Its words go into the notebook it has rather than a new empty one.
      const { meaningLang } = answers;
      if (meaningLang === undefined) return; // no step that writes is reachable without it
      const owned = (await listNotebooks()).find((notebook) => notebook.role === 'owner');
      const notebookId =
        owned?.id ??
        (await addNotebook({
          title: LANGUAGE_NAMES[answers.targetLang],
          targetLang: answers.targetLang,
          meaningLang,
          isDefault: true,
        }));

      // The look this device shows (its own, or what Settings set) joins
      // the account's settings, so the next device starts the same way.
      await patchSettings({ theme, palette });

      if (answers.serverFile !== undefined) {
        // The server reads the package into the notebook, so the notebook
        // has to be there first, and this device has the words once it pulls.
        setImportingAnki(true);
        await pushAll();
        const job = await waitForImport(
          (await sendImport(notebookId, answers.serverFile.source, answers.serverFile.file)).id,
        );
        if (job.status === 'failed')
          throw new ServerImportFailed(serverImportFailure(job, answers.serverFile.source));
        await syncNow();
      } else if (answers.imported.length > 0) {
        await importWords(notebookId, answers.imported, timeZone);
        reportImport(
          {
            kind: importKind.current,
            outcome: 'done',
            rowsTotal: answers.imported.length + importSkipped.current,
            rowsAdded: answers.imported.length,
            ...(importSkipped.current > 0 ? { rowsSkipped: importSkipped.current } : {}),
          },
          importFile.current,
        );
      } else if (answers.headword.trim() !== '') {
        const draft: WordDraft = answers.card
          ? { ...answers.card, meaning: answers.meaning || answers.card.meaning }
          : { headword: answers.headword.trim(), meaning: answers.meaning.trim() };
        await addWord(notebookId, draft, timeZone);
      }
      await setMeta('onboarded', true);

      void syncSoon();
      finished.current = true;
      const started =
        answers.imported.length > 0 || answers.serverFile !== undefined || answers.headword.trim() !== '';
      void navigate(started ? '/session' : (takeAfterSetup() ?? '/'), { replace: true });
    } catch (cause) {
      // A file the server could not take is let go, so the next tap goes
      // on without it (or with another file) instead of failing again.
      if (answers.serverFile !== undefined) {
        // A file the server never got cannot report itself.
        if (!(cause instanceof ServerImportFailed)) {
          const { file } = answers.serverFile;
          reportImportFailure(answers.serverFile.source, cause, { data: file, name: file.name });
        }
        const { serverFile: _failed, ...rest } = answers;
        setPicked(rest);
      }
      setError(
        cause instanceof ServerImportFailed
          ? cause.message
          : answers.serverFile !== undefined
            ? uploadFailure(cause, answers.serverFile.source)
            : isApiError(cause, 'offline')
              ? t('settings.importNeedsNetwork')
              : t('onboarding.failed'),
      );
      setImportingAnki(false);
      setBusy(false);
      finishing.current = false;
    }
  };

  const [aiState, setAiState] = useState<'idle' | 'working' | 'failed' | 'offline'>('idle');
  // The job that wrote the card, so Report on it can name it.
  const [cardJob, setCardJob] = useState<string | undefined>(undefined);

  /**
   * Writes the first card with the model, as a taste of what every entry can
   * become. The notebook has to exist on the server first, so it is created
   * here rather than at the end; finish() reuses it. There is an account by
   * now, so this is the first moment AI may run: never on the introduction.
   */
  const fillWithAi = async (): Promise<void> => {
    const headword = answers.headword.trim();
    if (headword === '' || aiState === 'working') return;
    setAiState('working');
    try {
      const { meaningLang } = answers;
      if (meaningLang === undefined) return; // no step that writes is reachable without it
      const owned = (await listNotebooks()).find((notebook) => notebook.role === 'owner');
      const notebookId =
        owned?.id ??
        (await addNotebook({
          title: LANGUAGE_NAMES[answers.targetLang],
          targetLang: answers.targetLang,
          meaningLang,
          isDefault: true,
        }));
      await pushAll();
      const { card, jobId } = await generateCardWithJob(notebookId, headword);
      setCardJob(jobId);
      set({ card, meaning: card.meaning });
      setAiState('idle');
    } catch (cause) {
      setAiState(isApiError(cause, 'offline') ? 'offline' : 'failed');
    }
  };

  // Back on a step of a pass that already ended (Back from the first card):
  // the notebook exists, so there is nothing left to ask.
  if (!editing && finishedRuns.has(run)) return <Navigate to="/" replace />;

  const targetName = LANGUAGE_NAMES[answers.targetLang];
  // Nothing that needs a direction is on screen before the second question
  // is answered; left to right is only what an empty picker lays out as.
  const meaningDir = answers.meaningLang === undefined ? 'ltr' : directionOf(answers.meaningLang);
  const meaningName = answers.meaningLang === undefined ? '' : LANGUAGE_NAMES[answers.meaningLang];
  const hasWord = answers.headword.trim() !== '';
  // A card needs a meaning to be asked: a word without one would make an
  // empty first session, so the last step waits for it (typed or filled).
  const needsMeaning =
    step === 'first' && answers.imported.length === 0 && hasWord && answers.meaning.trim() === '';
  // Back is offered on every question after the first, and when changing an
  // existing notebook's languages there is also a way out.
  const canBack = index > 0 || (editing && index === 0);

  return (
    <main className={styles.wrap}>
      <div className={styles.head}>
        {canBack && (
          <button
            type="button"
            className={styles.back}
            aria-label={t('action.back')}
            onClick={() => {
              if (editing && index === 0) {
                void navigate(settingsPath('notebooks'), { replace: true });
                return;
              }
              void navigate(-1);
            }}
          >
            <Icon name="chevronLeft" size={20} weight={2} />
          </button>
        )}
        <div
          className={styles.track}
          role="progressbar"
          aria-valuenow={index + 1}
          aria-valuemax={STEPS.length}
          aria-label={t('onboarding.step', { step: index + 1, total: STEPS.length })}
        >
          <div className={styles.fill} style={{ width: `${String(((index + 1) / STEPS.length) * 100)}%` }} />
        </div>
      </div>

      {step === 'target' && (
        <>
          <div className={styles.intro}>
            <h1 className={styles.title}>{t('onboarding.targetLang')}</h1>
            <p className={styles.lead}>{t('onboarding.targetLangLead')}</p>
          </div>
          <LanguagePicker
            label={t('onboarding.targetLang')}
            codes={TARGET_LANGUAGES}
            value={answers.targetLang}
            onPick={(targetLang) => {
              set({ targetLang });
              next({ targetLang });
            }}
          />
        </>
      )}

      {step === 'meaning' && (
        <>
          <div className={styles.intro}>
            <h1 className={styles.title}>{t('onboarding.meaningLang')}</h1>
            <p className={styles.lead}>{t('onboarding.meaningLangLead')}</p>
            <p className={styles.hint}>{t('onboarding.meaningSameHint', { target: targetName })}</p>
            {leaving !== undefined && (
              <div className={styles.locked} role="alert">
                <strong>{t('onboarding.changeNeedsPro')}</strong>
                <span>
                  {t('onboarding.changeNeedsProWhy', {
                    language: (LANGUAGE_NAMES as Partial<Record<string, string>>)[leaving] ?? leaving,
                  })}
                </span>
                <button
                  type="button"
                  className={styles.next}
                  onClick={() => {
                    setPaywall(true);
                  }}
                >
                  {t('newNotebook.seePro')}
                </button>
              </div>
            )}
          </div>
          <LanguagePicker
            label={t('onboarding.meaningLang')}
            codes={MEANING_LANGUAGES}
            value={answers.meaningLang}
            onPick={(meaningLang) => {
              set({ meaningLang });
              if (editing && current) {
                const others = (notebooks ?? []).filter(
                  (one) => one.id !== current.id && one.role === 'owner',
                ).length;
                const blocked = changeNeedsPro(billing, others, current, {
                  targetLang: answers.targetLang,
                  meaningLang,
                });
                setLeaving(blocked);
                if (blocked !== undefined) return;
                void updateNotebook(current.id, { targetLang: answers.targetLang, meaningLang })
                  .then(() => syncSoon())
                  .then(() => navigate(settingsPath('notebooks'), { replace: true }));
                return;
              }
              next({ meaningLang });
            }}
          />
        </>
      )}

      {step === 'first' && (
        <>
          <div className={styles.intro}>
            <h1 className={styles.title}>{t('onboarding.firstWord')}</h1>
            <p className={styles.lead}>
              {answers.targetLang === answers.meaningLang
                ? t('onboarding.firstWordLeadSame', { target: targetName })
                : t('onboarding.firstWordLead', { target: targetName, meaning: meaningName })}
            </p>
          </div>
          <div className={styles.fields}>
            <input
              className={styles.input}
              value={answers.headword}
              dir={directionOf(answers.targetLang)}
              placeholder={t('onboarding.wordPlaceholder', { language: targetName })}
              aria-label={t('add.word')}
              autoCapitalize="off"
              spellCheck={false}
              onChange={(event) => {
                // A different word is a different card: the one written for
                // the old word no longer belongs to it.
                const { card: _written, ...rest } = answers;
                setPicked({
                  ...rest,
                  headword: event.target.value,
                  ...(answers.card ? { meaning: '' } : {}),
                });
              }}
            />
            <input
              className={styles.input}
              value={answers.meaning}
              dir={meaningDir}
              placeholder={t('onboarding.meaningPlaceholder', { language: meaningName })}
              aria-label={t('add.meaning')}
              onChange={(event) => {
                set({ meaning: event.target.value });
              }}
            />
          </div>
          {answers.card === undefined ? (
            <>
              <button
                type="button"
                className={styles.aiButton}
                disabled={!hasWord || aiState === 'working'}
                aria-busy={aiState === 'working'}
                onClick={() => {
                  void fillWithAi();
                }}
              >
                {aiState === 'working' ? (
                  <span className={styles.aiSpinner} aria-hidden="true" />
                ) : (
                  <Icon name="sparkles" size={16} weight={2} />
                )}
                <span className={styles.aiLabel}>
                  <span>
                    {aiState === 'working' ? t('onboarding.aiWorking') : t('onboarding.fillWithAi')}
                  </span>
                  <span className={styles.aiHint}>
                    {aiState === 'working' ? t('onboarding.aiWorkingHint') : t('onboarding.fillHint')}
                  </span>
                </span>
              </button>
              {aiState === 'working' && (
                // The card's shape arrives before its words, so the wait
                // reads as progress rather than as nothing happening.
                <div
                  className={cx(styles.preview, styles.previewPending)}
                  role="status"
                  aria-label={t('onboarding.aiWorking')}
                >
                  <Skeleton height={12} width={110} />
                  <Skeleton height={28} width="55%" />
                  <Skeleton height={14} width="40%" />
                  <Skeleton height={18} width="70%" />
                  <Skeleton height={14} width="90%" />
                  <Skeleton height={14} width="80%" />
                </div>
              )}
            </>
          ) : (
            answers.meaningLang !== undefined && (
              <CardPreview
                card={answers.card}
                targetLang={answers.targetLang}
                meaningLang={answers.meaningLang}
                jobId={cardJob}
              />
            )
          )}
          {aiState === 'failed' && <p className={styles.error}>{t('onboarding.aiFailed')}</p>}
          {aiState === 'offline' && <p className={styles.hint}>{t('onboarding.aiOffline')}</p>}
          {needsMeaning && aiState !== 'working' && (
            <p className={styles.hint} id="onboarding-needs-meaning">
              {t('intro.needMeaning')}
            </p>
          )}
          <button
            type="button"
            className={styles.importLink}
            onClick={() => {
              fileInput.current?.click();
            }}
          >
            {t('onboarding.orImport')}
          </button>
          <button
            type="button"
            className={styles.importLink}
            onClick={() => {
              setPasting(true);
            }}
          >
            {t('onboarding.orPaste')}
          </button>
          {pasting && (
            <PasteListSheet
              onRead={readPasted}
              onClose={() => {
                setPasting(false);
              }}
            />
          )}
          <input
            ref={fileInput}
            type="file"
            accept={IMPORT_ACCEPT}
            hidden
            aria-label={t('onboarding.orImport')}
            onChange={(event) => {
              const file = event.target.files?.[0];
              event.target.value = '';
              if (file) void readFile(file);
            }}
          />
          {answers.serverFile !== undefined && (
            <p className={styles.hint}>
              {answers.serverFile.source === 'kindle'
                ? importingAnki
                  ? t('onboarding.kindleImporting')
                  : t('onboarding.kindleReady')
                : importingAnki
                  ? t('onboarding.ankiImporting')
                  : t('onboarding.ankiReady')}
            </p>
          )}
          {answers.imported.length > 0 && answers.meaningLang !== undefined && (
            <>
              <p className={styles.hint}>{t('onboarding.imported', { count: answers.imported.length })}</p>
              <PreviewList
                rows={answers.imported}
                targetLang={answers.targetLang}
                meaningLang={answers.meaningLang}
              />
              {answers.importSwapped && <p className={styles.hint}>{t('import.swappedNote')}</p>}
              {canSwap(answers.imported) && (
                <button
                  type="button"
                  className={styles.importLink}
                  onClick={() => {
                    set({ imported: swapColumns(answers.imported), importSwapped: !answers.importSwapped });
                  }}
                >
                  {t('import.swap')}
                </button>
              )}
            </>
          )}
        </>
      )}

      {error !== undefined && (
        <p className={styles.error} role="alert">
          {error}
        </p>
      )}

      <span className={styles.spacer} />

      <button
        type="button"
        className={styles.next}
        disabled={busy || needsMeaning}
        aria-describedby={needsMeaning ? 'onboarding-needs-meaning' : undefined}
        onClick={() => {
          if (step === 'first') void finish();
          else next();
        }}
      >
        {step === 'first'
          ? t(
              answers.imported.length > 0 || answers.serverFile !== undefined || hasWord
                ? 'onboarding.finish'
                : 'onboarding.finishEmpty',
            )
          : t('onboarding.next')}
      </button>
      {paywall && (
        <Upgrade
          onClose={() => {
            setPaywall(false);
          }}
        />
      )}
    </main>
  );
}

/** The finished card, laid out like the word screen, so the promise is shown rather than told. */
function CardPreview({
  card,
  targetLang,
  meaningLang,
  jobId,
}: {
  card: WordDraft;
  targetLang: LanguageCode;
  meaningLang: LanguageCode;
  jobId: string | undefined;
}): React.JSX.Element {
  const meta = [card.pronunciation, card.pos, card.level].filter((part) => part !== undefined && part !== '');
  const senses = [
    { meaning: card.meaning, gloss: card.gloss, example: card.example, translation: card.translation },
    ...(card.extraMeanings ?? []).map((sense) => ({
      meaning: sense.meaning,
      gloss: sense.gloss,
      example: sense.examples?.[0]?.sentence,
      translation: sense.examples?.[0]?.translation,
    })),
  ];
  return (
    <section className={styles.preview} aria-label={t('onboarding.aiPreview')}>
      <div className={styles.previewTop}>
        <p className={styles.previewKicker}>{t('onboarding.aiPreview')}</p>
        <ReportButton
          className={styles.previewReport}
          target={() => ({
            surface: 'card',
            snapshot: cardSnapshot(card),
            headword: card.headword,
            targetLang,
            meaningLang,
            aiJobId: jobId,
          })}
        />
      </div>
      <h2 className={styles.previewHeadword} dir={directionOf(targetLang)}>
        {card.correction ?? card.headword}
      </h2>
      {meta.length > 0 && <p className={styles.previewMeta}>{meta.join(' · ')}</p>}
      {senses.map((sense, index) => (
        <div key={index} className={styles.previewSense}>
          <p className={styles.previewMeaning} dir={directionOf(meaningLang)}>
            {sense.meaning}
          </p>
          {sense.gloss !== undefined && sense.gloss !== '' && (
            <p className={styles.previewGloss} dir={directionOf(targetLang)}>
              {sense.gloss}
            </p>
          )}
          {sense.example !== undefined && sense.example !== '' && (
            <blockquote className={styles.previewExample}>
              <p dir={directionOf(targetLang)}>{sense.example}</p>
              {sense.translation !== undefined && sense.translation !== '' && (
                <p className={styles.previewTranslation} dir={directionOf(meaningLang)}>
                  {sense.translation}
                </p>
              )}
            </blockquote>
          )}
        </div>
      ))}
      {(card.collocations?.length ?? 0) > 0 && (
        <div className={styles.previewGroup}>
          <p className={styles.previewLabel}>{t('onboarding.collocations')}</p>
          <div className={styles.chips} dir={directionOf(targetLang)}>
            {card.collocations?.map((chip) => (
              <span key={chip} className={styles.chip}>
                {chip}
              </span>
            ))}
          </div>
        </div>
      )}
      {(card.expressions?.length ?? 0) > 0 && (
        <div className={styles.previewGroup}>
          <p className={styles.previewLabel}>{t('onboarding.expressions')}</p>
          {card.expressions?.map((phrase) => (
            <p key={phrase.text} className={styles.previewLine}>
              <span dir={directionOf(targetLang)}>{phrase.text}</span>
              {phrase.translation !== undefined && phrase.translation !== '' && (
                <span className={styles.previewTranslation} dir={directionOf(meaningLang)}>
                  {' '}
                  — {phrase.translation}
                </span>
              )}
            </p>
          ))}
        </div>
      )}
      {(card.relatedWords?.length ?? 0) > 0 && (
        <div className={styles.previewGroup}>
          <p className={styles.previewLabel}>{t('onboarding.related')}</p>
          <div className={styles.chips} dir={directionOf(targetLang)}>
            {card.relatedWords?.map((phrase) => (
              <span key={phrase.text} className={styles.chip}>
                {phrase.text}
              </span>
            ))}
          </div>
        </div>
      )}
      <p className={styles.previewLead}>{t('onboarding.aiPreviewLead')}</p>
    </section>
  );
}

/** A file the server read and could not import, with the sentence to show. */
class ServerImportFailed extends Error {}
