import { Icon } from '@/components/ui/Icon.js';
import { db, setMeta } from '@/db/schema.js';
import { listNotebooks } from '@/db/repo.js';
import {
  addNotebook,
  addWord,
  editWord,
  enrichWord,
  importWords,
  patchSettings,
  type WordDraft,
} from '@/db/mutations.js';
import { auth as authApi } from '@/api/endpoints.js';
import { isApiError } from '@/api/errors.js';
import { AiJobFailed, generateCardWithJob, isUnrecognised } from '@/features/ai/generate.js';
import { knownUnknown, rememberUnknown } from '@/features/ai/unknownEntries.js';
import { isAiConsentDeclined } from '@/features/ai/consent.js';
import { useAuth } from '@/features/auth/session.js';
import { accountAddress } from '@/features/auth/hiddenEmail.js';
import { AddSheet } from '@/features/notebook/AddSheet.js';
import { suggestedSpelling } from '@/features/notebook/spelling.js';
import { ReportButton } from '@/features/report/ReportButton.js';
