/**
 * The first card (onboarding v2, uiux 2026-10-21 spec §4.8): what the
 * questions asked before the account, done at once now that one exists.
 * The notebook is created with the two languages, the plan's words a day go
 * to the settings, why/where/minutes to local meta (why and where also to
 * the account, once: features/intro/sendAnswers.ts), and AI writes the card
 * for the learner's own word straight away: the first moment AI may run.
 * Every way it can go has its own words (AI failed, offline, an address not
 * confirmed yet, a word not recognised, a spelling to suggest), and in each
 * the word is saved before anything else is asked, so leaving loses nothing.
 * Then three quick cards of that word (`/session?deck=first`).
 */
type Phase =
  'writing' | 'ready' | 'didYouMean' | 'failed' | 'offline' | 'unverified' | 'unrecognised' | 'manual';

/** Where this run stands, in its history entry, so a reload carries on rather than starting again. */
interface FirstState {
  draft?: unknown;
  notebookId?: unknown;
  wordId?: unknown;
}

/** The answers this run started from: this entry's own copy, else the stored draft. */
function startingDraft(state: FirstState | null): IntroDraft {
  return state?.draft !== undefined ? validDraft(state.draft) : readDraft();
}

export function FirstCard(): React.JSX.Element {
  const navigate = useNavigate();
  const location = useLocation();
  const [params] = useSearchParams();
  const kept = location.state as FirstState | null;
  const [draft] = useState(() => startingDraft(kept));
  const { theme, palette } = useTheme();
  const user = useAuth((state) => state.user);
  const [phase, setPhase] = useState<Phase>('writing');
  const [notebookId, setNotebookId] = useState<string | undefined>(
    typeof kept?.notebookId === 'string' ? kept.notebookId : undefined,
  );
  const [wordId, setWordId] = useState<string | undefined>(
    typeof kept?.wordId === 'string' ? kept.wordId : undefined,
  );
  const [headword, setHeadword] = useState(draft.word ?? '');
  const [card, setCard] = useState<WordDraft | undefined>(undefined);
  const [jobId, setJobId] = useState<string | undefined>(undefined);
  const [error, setError] = useState<string | undefined>(undefined);
  const [declined, setDeclined] = useState(false);
  const [editing, setEditing] = useState(false);
  const [pasting, setPasting] = useState(false);
  const started = useRef(false);
  const heading = useRef<HTMLHeadingElement>(null);
  const word = useLiveQuery(
    async () => (wordId === undefined ? undefined : await db.words.get(wordId)),
    undefined,
    [wordId],
  );

  const target: LanguageCode = draft.target ?? 'en';
  const meaning: LanguageCode = draft.meaning ?? target;
  const meaningName = LANGUAGE_NAMES[meaning];

  /** Keeps where the run stands in this history entry (a reload continues from it). */
  const stamp = (change: { notebookId?: string; wordId?: string }): void => {
    void navigate(`${location.pathname}${location.search}`, {
      replace: true,
      state: {
        draft,
        notebookId: change.notebookId ?? notebookId,
        wordId: change.wordId ?? wordId,
      } satisfies FirstState,
    });
  };

  /** The notebook, the settings and the answers: once, before anything else. */
  const setUp = async (): Promise<string> => {
    if (notebookId !== undefined) return notebookId;
    // An account that already owns a notebook got here by mistake, or a pull
    // landed meanwhile: the word goes into the notebook it has.
    const owned = (await listNotebooks()).find((notebook) => notebook.role === 'owner');
    const id =
      owned?.id ??
      (await addNotebook({
        title: LANGUAGE_NAMES[target],
        targetLang: target,
        meaningLang: meaning,
        isDefault: true,
      }));
    const minutes = planMinutes(draft.minutes, draft.why);
    await patchSettings({ theme, palette, newPerDay: planFor(minutes).newPerDay });
    await setMeta('onboardingGoals', draft.why);
    await setMeta('wordSources', draft.where);
    await setMeta('planMinutes', minutes);
    // The answers go to the account too, once (features/intro/sendAnswers.ts).
    if (draft.why.length > 0 || draft.where.length > 0) {
      await setMeta('onboardingAnswers', {
        goals: draft.why,
        sources: draft.where,
        at: new Date().toISOString(),
      });
    }
    // The reminder time and the goal from the introduction (sales plan G).
    await applyIntroChoices(draft);
    await setMeta('onboarded', true);
    void sendOnboardingAnswers();
    setNotebookId(id);
    return id;
  };

  /** Saves the word as it is, so it is safe whatever happens next. */
  const keepPlain = async (into: string, text: string): Promise<string> => {
    if (wordId !== undefined) return wordId;
    const id = await addWord(into, { headword: text, meaning: '' }, localTimeZone());
    setWordId(id);
    stamp({ notebookId: into, wordId: id });
    void syncSoon();
    return id;
  };

  /** Asks AI for the card; every way it can end has its own state. */
  const write = async (text: string): Promise<void> => {
    setPhase('writing');
    setError(undefined);
    setDeclined(false);
    let into: string;
    try {
      into = await setUp();
    } catch {
      setPhase('failed');
      setError(t('onb.card.failed'));
      return;
    }
    try {
      // The notebook has to be on the server before a card is asked for it.
      await pushAll();
      const made = await generateCardWithJob(into, text);
      setJobId(made.jobId);
      if (suggestedSpelling(text, made.card.correction) !== undefined) {
        setCard(made.card);
        setPhase('didYouMean');
        return;
      }
      await keepCard(into, made.card, made.jobId);
    } catch (cause) {
      const plain = await keepPlain(into, text).catch(() => undefined);
      if (plain === undefined) {
        setPhase('failed');
        return;
      }
      if (isAiConsentDeclined(cause)) {
        // "Not now" on the AI question: the learner's choice, not a failure.
        setDeclined(true);
        setPhase('failed');
      } else if (isApiError(cause, 'offline')) setPhase('offline');
      else if (isApiError(cause) && cause.code === 'email_unverified') setPhase('unverified');
      else if (cause instanceof AiJobFailed && isUnrecognised(cause)) {
        rememberUnknown(target, [text]);
        setPhase('unrecognised');
      } else setPhase('failed');
    }
  };

  /** The card the model wrote, saved with the word. */
  const keepCard = async (into: string, made: WordDraft, job: string | undefined): Promise<void> => {
    let id = wordId;
    if (id === undefined) {
      id = await addWord(into, { ...made, source: 'ai' }, localTimeZone());
      setWordId(id);
    } else {
      if (made.headword !== '' && made.headword !== headword) await editWord(id, { headword: made.headword });
      await enrichWord(id, made, db, job);
    }
    stamp({ notebookId: into, wordId: id });
    void syncSoon();
    setCard(made);
    setPhase('ready');
    platform.haptics.confirm();
  };

  // Runs once. A reload of a run that already saved its word picks up from it.
  useEffect(() => {
    if (started.current) return;
    started.current = true;
    // The draft now lives in this entry; the stored copy goes.
    stamp({});
    clearDraft();
    void (async () => {
      if (draft.word === undefined) {
        // "I'll add words later": the notebook and the plan, then Today, or
        // the paste box when a link asked for it.
        try {
          await setUp();
          void syncSoon();
          if (params.get('import') === 'paste') setPasting(true);
          else void navigate(takeAfterSetup() ?? '/', { replace: true });
        } catch {
          setPhase('failed');
          setError(t('onb.card.failed'));
        }
        return;
      }
      if (wordId !== undefined) {
        const saved = await db.words.get(wordId);
        const hasMeaning = (saved?.meanings ?? []).some((sense) => sense.meaning.trim() !== '');
        if (saved !== undefined && hasMeaning) {
          setHeadword(saved.headword);
          setPhase('ready');
          return;
        }
      }
      await write(draft.word);
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps -- once per run
  }, []);

  // Each state is announced by its title.
  useEffect(() => {
    heading.current?.focus({ preventScroll: true });
  }, [phase]);

  const practise = (id: string | undefined): void => {
    if (id === undefined) return;
    void navigate(`/session?deck=first&word=${encodeURIComponent(id)}`, { replace: true });
  };

  const [manualMeaning, setManualMeaning] = useState('');
  const [manualExample, setManualExample] = useState('');
  const [fix, setFix] = useState(headword);
  const [resent, setResent] = useState(false);
  const saveManual = async (): Promise<void> => {
    const into = notebookId ?? (await setUp());
    const id = wordId ?? (await keepPlain(into, headword));
    await enrichWord(id, {
      headword,
      meaning: manualMeaning.trim(),
      ...(manualExample.trim() === '' ? {} : { example: manualExample.trim() }),
    });
    void syncSoon();
    practise(id);
  };

  const manualFields =
    phase === 'failed' || phase === 'offline' || phase === 'unverified' || phase === 'manual';
  const copy = ((): { title: string; lead: string } => {
    switch (phase) {
      case 'writing':
        return { title: t('onb.card.writing'), lead: t('onb.card.writingLead', { language: meaningName }) };
      case 'ready':
        return { title: t('onb.card.ready'), lead: t('onb.card.readyLead') };
      case 'didYouMean': {
        const suggestion = suggestedSpelling(headword, card?.correction) ?? headword;
        return {
          title: t('onb.card.didYouMean', { word: suggestion }),
          lead: t('onb.card.dymLead', { typed: headword }),
        };
      }
      case 'failed':
        return {
          title: t('onb.card.failTitle'),
          lead: error ?? (declined ? t('onb.card.declinedLead') : t('onb.card.failLead')),
        };
      case 'offline':
        return { title: t('onb.card.offTitle'), lead: t('onb.card.offLead') };
      case 'unverified':
        return { title: t('onb.card.unvTitle'), lead: t('onb.card.unvLead') };
      case 'unrecognised':
        return {
          title: t('onb.card.unrTitle'),
          lead: t('onb.card.unrLead', { word: headword, language: LANGUAGE_NAMES[target] }),
        };
      case 'manual':
        return { title: t('onb.card.failTitle'), lead: t('onb.card.manualLead') };
    }
  })();

  if (pasting && notebookId !== undefined) {
    return (
      <main className={styles.screen}>
        <PasteListSheet
          onRead={(text) => {
            setPasting(false);
            void (async () => {
              try {
                const parsed = parseFile('pasted.txt', text, { targetLang: target, meaningLang: meaning });
                await importWords(notebookId, parsed.rows, localTimeZone());
                void syncSoon();
                void navigate('/', { replace: true });
              } catch (cause) {
                setError(importErrorMessage(cause));
                setPhase('failed');
              }
            })();
          }}
          onClose={() => {
            void navigate('/', { replace: true });
          }}
        />
      </main>
    );
  }

  const suggestion = phase === 'didYouMean' ? suggestedSpelling(headword, card?.correction) : undefined;
  return (
    <main className={styles.screen}>
      <div className={styles.scroll}>
        <div className={styles.col}>
          <h1 ref={heading} className={styles.title} tabIndex={-1} aria-live="polite">
            {copy.title}
          </h1>
          <p className={styles.lead}>{copy.lead}</p>
          <section
            className={cx(styles.card, phase === 'ready' && styles.built)}
            aria-busy={phase === 'writing'}
          >
            <div className={styles.top}>
              <span className={styles.aiChip}>
                <Icon name="sparkles" size={13} weight={2} />
                {phase === 'writing'
                  ? t('onb.card.writingChip')
                  : phase === 'ready' && word?.source === 'ai'
                    ? t('onb.s2.written')
                    : t('onb.card.yours')}
              </span>
              <span className={styles.tools}>
                {phase === 'ready' && word?.source === 'ai' && card !== undefined && (
                  <ReportButton
                    variant="icon"
                    className={styles.report}
                    target={() => ({
                      surface: 'card',
                      snapshot: cardSnapshot(card),
                      headword: card.headword,
                      targetLang: target,
                      meaningLang: meaning,
                      aiJobId: jobId,
                    })}
                  />
                )}
                <span className={styles.speaker}>
                  <Speaker text={word?.headword ?? headword} lang={target} />
                </span>
              </span>
            </div>
            <h2 className={styles.headword} dir={directionOf(target)} lang={target}>
              {word?.headword ?? headword}
            </h2>
            {phase === 'writing' && (
              <div className={styles.skeleton} role="status" aria-label={t('onb.card.writing')}>
                {[46, 88, 72, 80, 60].map((width) => (
                  <i key={width} style={{ width: `${String(width)}%` }} />
                ))}
              </div>
            )}
            {phase === 'ready' && word !== undefined && (
              <CardBody word={word} target={target} meaning={meaning} />
            )}
            {manualFields && (
              <div className={styles.fields}>
                <input
                  className={styles.field}
                  value={manualMeaning}
                  dir={directionOf(meaning)}
                  lang={meaning}
                  placeholder={t('onb.card.meaning', { language: meaningName })}
                  aria-label={t('onb.card.meaning', { language: meaningName })}
                  onChange={(event) => {
                    setManualMeaning(event.target.value);
                  }}
                />
                <input
                  className={styles.field}
                  value={manualExample}
                  dir={directionOf(target)}
                  lang={target}
                  placeholder={t('onb.card.example')}
                  aria-label={t('onb.card.example')}
                  onChange={(event) => {
                    setManualExample(event.target.value);
                  }}
                />
              </div>
            )}
            {phase === 'unrecognised' && (
              <div className={styles.fields}>
                <input
                  className={styles.field}
                  value={fix}
                  dir="auto"
                  lang={target}
                  aria-label={t('onb.word.placeholder')}
                  autoCapitalize="off"
                  autoCorrect="off"
                  spellCheck={false}
                  onChange={(event) => {
                    setFix(event.target.value);
                  }}
                />
              </div>
            )}
          </section>
          {phase === 'didYouMean' &&
            suggestion !== undefined &&
            card !== undefined &&
            notebookId !== undefined && (
              <div className={styles.row2}>
                <button
                  type="button"
                  className={styles.secondary}
                  onClick={() => {
                    // Keep mine: the suggestion stays on the word for its own page to ask again.
                    void keepCard(notebookId, card, jobId);
                  }}
                >
                  {t('onb.card.keep')}
                </button>
                <button
                  type="button"
                  className={cx(styles.primary, styles.primarySmall)}
                  onClick={() => {
                    // The card is already for the suggested word: Use renames, nothing goes back to the model.
                    const { correction: _used, ...rest } = card;
                    setHeadword(suggestion);
                    void keepCard(notebookId, { ...rest, headword: suggestion }, jobId);
                  }}
                >
                  {t('onb.card.use', { word: suggestion })}
                </button>
              </div>
            )}
          {phase === 'unverified' && (
            <>
              <div className={styles.notice} role="note">
                <b>{t('onb.card.unvNoteTitle')}</b>
                {t('onb.card.unvNote', { email: user === null ? '' : accountAddress(user) })}
              </div>
              <button
                type="button"
                className={styles.quiet}
                disabled={resent}
                onClick={() => {
                  void authApi.resendVerification().then(
                    () => {
                      setResent(true);
                    },
                    () => undefined,
                  );
                }}
              >
                {resent ? t('onb.card.resent') : t('onb.card.resend')}
              </button>
            </>
          )}
          {phase === 'failed' && (
            <button
              type="button"
              className={styles.quiet}
              onClick={() => {
                void write(headword);
              }}
            >
              {t('onb.card.aiAgain')}
            </button>
          )}
        </div>
      </div>
      {phase !== 'didYouMean' && (
        <div className={styles.foot}>
          {phase === 'unrecognised' ? (
            <>
              <button
                type="button"
                className={styles.primary}
                // The same text gets the same answer: Try again waits for a change.
                disabled={fix.trim() === '' || knownUnknown(target, fix)}
                onClick={() => {
                  const next = fix.replace(/\s+/gu, ' ').trim();
                  void (async () => {
                    if (wordId !== undefined && next !== headword) await editWord(wordId, { headword: next });
                    setHeadword(next);
                    await write(next);
                  })();
                }}
              >
                {t('onb.card.retry')}
              </button>
              <button
                type="button"
                className={styles.quiet}
                onClick={() => {
                  setPhase('manual');
                }}
              >
                {t('onb.card.keepMine')}
              </button>
            </>
          ) : manualFields ? (
            <button
              type="button"
              className={styles.primary}
              disabled={manualMeaning.trim() === ''}
              onClick={() => {
                void saveManual();
              }}
            >
              {t('onb.card.save')}
            </button>
          ) : (
            <>
              <button
                type="button"
                className={styles.primary}
                disabled={phase !== 'ready'}
                onClick={() => {
                  practise(wordId);
                }}
              >
                {t('onb.card.practise')}
              </button>
              {phase === 'ready' && (
                <button
                  type="button"
                  className={styles.quiet}
                  onClick={() => {
                    setEditing(true);
                  }}
                >
                  {t('onb.card.edit')}
                </button>
              )}
            </>
          )}
        </div>
      )}
      {editing && word !== undefined && (
        <AddSheet
          edit={word}
          notebookId={word.notebookId}
          targetLang={target}
          meaningLang={meaning}
          onClose={() => {
            setEditing(false);
          }}
        />
      )}
    </main>
  );
}

/** The headword marked inside a sentence, as the word page does. */
function marked(sentence: string, headword: string): React.ReactNode {
  const at = sentence.toLocaleLowerCase().indexOf(headword.toLocaleLowerCase());
  if (headword === '' || at < 0) return sentence;
  return (
    <>
      {sentence.slice(0, at)}
      <b>{sentence.slice(at, at + headword.length)}</b>
      {sentence.slice(at + headword.length)}
    </>
  );
}

/** The card's parts, rising in order once it is written (spec §4.8 step 3). */
function CardBody({
  word,
  target,
  meaning,
}: {
  word: Word;
  target: LanguageCode;
  meaning: LanguageCode;
}): React.JSX.Element {
  const sense = word.meanings?.[0];
  const example = sense?.examples?.[0];
  const meta = [word.pos, word.level].filter((part): part is string => part !== undefined && part !== '');
  // The definition in the language learnt leads; the meaning in the
  // learner's own language sits under it with its language named. A notebook
  // in one language (English definitions) has only the one line.
  const definition = sense?.gloss !== undefined && sense.gloss !== '' ? sense.gloss : undefined;
  return (
    <>
      {(word.pronunciation !== undefined || meta.length > 0) && (
        <div className={cx(styles.meta, styles.rise)}>
          {word.pronunciation !== undefined && word.pronunciation !== '' && (
            <span className={styles.ipa}>{word.pronunciation}</span>
          )}
          {meta.map((part) => (
            <span key={part} className={styles.tag}>
              {part}
            </span>
          ))}
        </div>
      )}
      {sense !== undefined && (
        <div className={cx(styles.sense, styles.rise)} style={{ animationDelay: '60ms' }}>
          <span className={styles.num}>1</span>
          <div>
            <p className={styles.mean} dir={directionOf(definition === undefined ? meaning : target)}>
              {definition ?? sense.meaning}
            </p>
            {definition !== undefined && (
              <div className={styles.trans}>
                <span className={styles.lang}>{meaning.toUpperCase()}</span>
                <span className={styles.tword} dir={directionOf(meaning)} lang={meaning}>
                  {sense.meaning}
                </span>
              </div>
            )}
            {example !== undefined && (
              <>
                <p className={styles.ex} dir={directionOf(target)} lang={target}>
                  {marked(example.sentence, word.headword)}
                </p>
                {example.translation !== undefined && example.translation !== '' && (
                  <p className={styles.exTrans} dir={directionOf(meaning)} lang={meaning}>
                    {example.translation}
                  </p>
                )}
              </>
            )}
          </div>
        </div>
      )}
      {(word.collocations?.length ?? 0) > 0 && (
        <div
          className={cx(styles.colls, styles.rise)}
          style={{ animationDelay: '120ms' }}
          dir={directionOf(target)}
        >
          {word.collocations?.map((chip) => (
            <span key={chip}>{chip}</span>
          ))}
        </div>
      )}
    </>
  );
}
