import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ApiError } from '@/api/errors.js';
import { AppleMark, GoogleMark, Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { platform } from '@/lib/platform/index.js';
import { isSignInCancelled } from '@/features/auth/appleSignIn.js';
import { dismissLinkOffer } from '@/features/auth/linkOffer.js';
import { googleProof, ProofCancelled, useAppleProof } from '@/features/auth/providerProof.js';
import { authMessageFor, useAuth, type JoinProof } from '@/features/auth/session.js';
import { settingsPath } from '@/features/settings/paths.js';
import auth from '@/features/auth/SignIn.module.css';
import styles from './ExistingAccount.module.css';

/**
 * Asked once, before onboarding, of an account Sign in with Apple has just
 * made with a hidden address: such an address matches nothing, so somebody
 * who already had an account gets a second, empty one. "I already have an
 * account" signs in to that one (password or Google) and hands Apple over to
 * it; the empty account is then deleted by the server. "I'm new" carries on
 * to onboarding. Either answer ends the question for good.
 */
export function ExistingAccount({ onNew }: { onNew: () => void }): React.JSX.Element {
  const navigate = useNavigate();
  const join = useAuth((state) => state.joinExistingAccount);
  const signInWithApple = useAuth((state) => state.signInWithApple);
  const appleProof = useAppleProof();
  const [step, setStep] = useState<'ask' | 'signIn'>('ask');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [busy, setBusy] = useState(false);
  const [problem, setProblem] = useState<string | undefined>(undefined);
  // The question can outlive the five minutes a sign-in counts as recent;
  // Apple once more is then the proof that this new account is theirs.
  const [needsApple, setNeedsApple] = useState(false);

  const run = (proof: JoinProof): void => {
    setBusy(true);
    setProblem(undefined);
    join(proof)
      .then((outcome) => {
        void navigate(settingsPath('account'), {
          replace: true,
          state: { joined: outcome.problem ?? true },
        });
      })
      .catch((cause: unknown) => {
        setBusy(false);
        if (cause instanceof ApiError && cause.code === 'reauth_required') {
          setNeedsApple(true);
          setProblem(t('join.confirmApple'));
        } else if (cause instanceof ApiError && cause.code === 'account_not_empty') {
          setProblem(t('join.notEmpty'));
        } else setProblem(authMessageFor(cause));
      });
  };

  const withGoogle = (): void => {
    setProblem(undefined);
    googleProof()
      .then((credential) => {
        run({ kind: 'google', credential });
      })
      .catch((cause: unknown) => {
        if (cause instanceof ProofCancelled || isSignInCancelled(cause)) return;
        setProblem(t('auth.providerFailed', { provider: 'Google' }));
      });
  };

  const confirmApple = (): void => {
    setProblem(undefined);
    appleProof()
      .then((proof) => signInWithApple(proof))
      .then(() => {
        setNeedsApple(false);
        setProblem(t('join.appleConfirmed'));
      })
      .catch((cause: unknown) => {
        if (!isSignInCancelled(cause)) setProblem(t('auth.providerFailed', { provider: 'Apple' }));
      });
  };

  const brand = (
    <div className={auth.brand}>
      <div className={styles.marks} aria-hidden="true">
        <span className={auth.mark}>
          <Icon name="notebook" size={22} weight={2} />
        </span>
        <span className={styles.plus}>+</span>
        <span className={styles.appleMark}>
          <AppleMark size={22} />
        </span>
      </div>
      <h1 className={auth.name}>{step === 'ask' ? t('join.title') : t('join.signInTitle')}</h1>
      <p className={auth.tagline}>{step === 'ask' ? t('join.lead') : t('join.signInLead')}</p>
    </div>
  );

  if (step === 'ask') {
    return (
      <main className={auth.wrap}>
        {brand}
        <div className={auth.form}>
          <button
            type="button"
            className={auth.submit}
            onClick={() => {
              setStep('signIn');
            }}
          >
            {t('join.haveAccount')}
          </button>
          <button
            type="button"
            className={styles.secondary}
            onClick={() => {
              dismissLinkOffer();
              onNew();
            }}
          >
            {t('join.imNew')}
          </button>
          <p className={auth.note}>{t('join.laterNote')}</p>
        </div>
      </main>
    );
  }

  return (
    <main className={auth.wrap}>
      {brand}
      <form
        className={auth.form}
        noValidate
        onSubmit={(event) => {
          event.preventDefault();
          if (!email.includes('@') || password === '') {
            setProblem(t('join.fillIn'));
            return;
          }
          run({ kind: 'password', email: email.trim(), password });
        }}
      >
        <input
          className={auth.input}
          type="email"
          placeholder={t('auth.email')}
          aria-label={t('auth.email')}
          autoComplete="email"
          inputMode="email"
          autoCapitalize="off"
          spellCheck={false}
          value={email}
          onChange={(event) => {
            setEmail(event.target.value);
          }}
        />
        <input
          className={auth.input}
          type="password"
          placeholder={t('auth.password')}
          aria-label={t('auth.password')}
          autoComplete="current-password"
          value={password}
          onChange={(event) => {
            setPassword(event.target.value);
          }}
        />
        {problem !== undefined && (
          <div className={auth.error} role="alert">
            {problem}
          </div>
        )}
        {needsApple && (
          <button type="button" className={auth.apple} onClick={confirmApple}>
            <AppleMark size={20} />
            {t('join.confirmAppleButton')}
          </button>
        )}
        <button type="submit" className={auth.submit} disabled={busy}>
          {busy ? t('auth.busy') : t('join.signInAndConnect')}
        </button>
        {platform.env.googleClientId !== '' && (
          <>
            <div className={auth.divider}>
              <span className={auth.rule} />
              <span className={auth.dividerLabel}>{t('auth.or')}</span>
              <span className={auth.rule} />
            </div>
            <button type="button" className={auth.google} disabled={busy} onClick={withGoogle}>
              <GoogleMark size={20} />
              {t('auth.google')}
            </button>
          </>
        )}
        <p className={auth.note}>{t('join.whatHappens')}</p>
      </form>
      <button
        type="button"
        className={auth.switch}
        disabled={busy}
        onClick={() => {
          setStep('ask');
          setProblem(undefined);
        }}
      >
        {t('join.back')}
      </button>
    </main>
  );
}
