import { useState } from 'react';
import { useLocation, useSearchParams } from 'react-router-dom';
import { useAuth } from '@/features/auth/session.js';
import { linkOfferPending } from '@/features/auth/linkOffer.js';
import { hasDraft } from '@/features/intro/introDraft.js';
import { ExistingAccount } from './ExistingAccount.js';
import { FirstCard } from './FirstCard.js';
import { Onboarding } from './Onboarding.js';

/**
 * The first-run screen. An account Sign in with Apple has just made with a
 * hidden address is asked once whether the learner already has an account
 * (ExistingAccount). Somebody who answered the introduction's questions
 * before the account (onboarding v2) goes straight to their first card,
 * with nothing asked twice; anyone else (an account made on the sign-in
 * page, a new device with an empty notebook) gets the questions here.
 */
export function Welcome(): React.JSX.Element {
  const userId = useAuth((state) => state.user?.id);
  const [params] = useSearchParams();
  const [answered, setAnswered] = useState(false);
  // Read once: the first card takes the draft into its own history entry.
  const location = useLocation();
  const [fromIntro] = useState(
    () => (location.state as { draft?: unknown } | null)?.draft !== undefined || hasDraft(),
  );
  const ask = !answered && params.get('edit') !== '1' && linkOfferPending(userId);
  if (ask) {
    return (
      <ExistingAccount
        onNew={() => {
          setAnswered(true);
        }}
      />
    );
  }
  if (fromIntro && params.get('edit') !== '1') return <FirstCard />;
  return <Onboarding />;
}
